"""Upload authorization and exemptions for preexisting projects."""

from .grants import _validate_namespace, _validate_owner
from .normalize import normalize_name

__all__ = [
    'CONFLICT_STATUS', 'UploadConflictError', 'GrandfatheredRegistry',
    'authorize_upload',
]

CONFLICT_STATUS = 409


class UploadConflictError(Exception):
    """An uploader attempted to use a namespace owned by someone else."""

    status_code = CONFLICT_STATUS

    def __init__(self, project, namespace, owner):
        self.project = normalize_name(project)
        self.namespace = normalize_name(namespace)
        self.owner = owner
        super().__init__(
            f'409 Conflict: {self.project!r} matches namespace '
            f'{self.namespace!r}; upload by {owner!r} denied')


class GrandfatheredRegistry:
    """Track normalized project names exempt from namespace upload checks."""

    def __init__(self, projects=()):
        self._projects = set()
        for project in projects:
            self.add(project)

    def __len__(self):
        return len(self._projects)

    def __contains__(self, project):
        return (isinstance(project, str)
                and normalize_name(project) in self._projects)

    def add(self, project):
        """Exempt one exact project name, without exempting its descendants."""
        self._projects.add(_validate_namespace(project))

    def discard(self, project):
        """Remove an exemption if it exists."""
        self._projects.discard(normalize_name(project))

    def covers(self, project):
        """Return whether the normalized project has an exemption."""
        return project in self

    def projects(self):
        """Return exempt project names in sorted order."""
        return sorted(self._projects)


def authorize_upload(project, owner, store, grandfathered=None, *,
                     raise_on_conflict=False):
    """Return whether an upload is allowed, optionally raising on conflict."""
    _validate_owner(owner)
    project = _validate_namespace(project)
    if grandfathered is not None and grandfathered.covers(project):
        return True
    for grant in store.matching(project):
        if grant.owner != owner:
            if raise_on_conflict:
                raise UploadConflictError(project, grant.name, owner)
            return False
    return True
"""Repository-specific installation policies for package namespaces."""

from .grants import _validate_namespace, _validate_owner
from .matching import namespace_matches
from .normalize import normalize_name

__all__ = ['SecurityPolicy']


class SecurityPolicy:
    """Require project and grant ownership in selected namespaces."""

    def __init__(self, namespaces, owner):
        _validate_owner(owner)
        self._owner = owner
        self._namespaces = sorted({_validate_namespace(name)
                                   for name in namespaces})

    @property
    def owner(self):
        """The required project and grant owner."""
        return self._owner

    @property
    def namespaces(self):
        """A sorted copy of the normalized policy namespace names."""
        return self._namespaces.copy()

    def allows(self, project, index):
        """Require matching project ownership and a grant on this index."""
        project = normalize_name(project)
        if not index.supports_namespaces:
            return False
        if index.project_owner(project) != self.owner:
            return False
        for namespace in self._namespaces:
            grant = index.store.get(namespace)
            if (grant is not None and grant.owner == self.owner
                    and namespace_matches(namespace, project)):
                return True
        return False

    def evaluate(self, requirements, index):
        """Map normalized project names to policy decisions on *index*."""
        return {normalize_name(project): self.allows(project, index)
                for project in requirements}
import html
import re
import unittest

try:
    from packagenamespaces import GrantStore, UnknownGrantError
    from packagenamespaces.metadata import (
        API_VERSION,
        LEGACY_API_VERSION,
        NotSupportedError,
        RepositoryIndex,
    )
except Exception as exc:
    _IMPORT_ERROR = exc
else:
    _IMPORT_ERROR = None


class MetadataTests(unittest.TestCase):
    def require_impl(self):
        if _IMPORT_ERROR is not None:
            self.fail(f"Cannot import the namespace API: {_IMPORT_ERROR}")

    def make_index(self):
        store = GrantStore()
        store.reserve("acme-widgets", "acme-corp")
        store.reserve("acme", "acme-corp")
        return store, RepositoryIndex(store)

    def test_namespace_list_empty(self):
        self.require_impl()
        self.assertEqual(RepositoryIndex().list_namespaces(), [])

    def test_namespace_list_shape(self):
        self.require_impl()
        _, index = self.make_index()
        self.assertEqual(
            index.list_namespaces(),
            [{"name": "acme"}, {"name": "acme-widgets"}],
        )

    def test_namespace_detail_shape(self):
        self.require_impl()
        _, index = self.make_index()
        expected = {
            "acme-widgets": {
                "owner": "acme-corp",
                "children": [],
                "parent": "acme",
                "name": "acme-widgets",
            },
            "acme": {
                "owner": "acme-corp",
                "children": ["acme-widgets"],
                "parent": None,
                "name": "acme",
            },
        }
        for name, detail in expected.items():
            with self.subTest(namespace=name):
                self.assertEqual(index.namespace_detail(name), detail)

    def test_namespace_detail_children_direct_only(self):
        self.require_impl()
        store = GrantStore()
        for name in ("foo-bar-baz", "foo-bar", "foo"):
            store.reserve(name, "acme-corp")
        index = RepositoryIndex(store)
        self.assertEqual(index.namespace_detail("foo")["children"], ["foo-bar"])

    def test_namespace_detail_parent_null_without_grant(self):
        self.require_impl()
        store = GrantStore()
        store.reserve("deep-down-namespace", "acme-corp")
        index = RepositoryIndex(store)
        self.assertIsNone(index.namespace_detail("deep-down-namespace")["parent"])

    def test_namespace_detail_unknown_raises(self):
        self.require_impl()
        _, index = self.make_index()
        with self.assertRaises(UnknownGrantError):
            index.namespace_detail("no-such-namespace")

    def test_namespace_detail_normalizes_input(self):
        self.require_impl()
        _, index = self.make_index()
        self.assertEqual(
            index.namespace_detail("Acme.Widgets")["name"], "acme-widgets"
        )

    def test_project_detail_multiple_matches_sorted(self):
        self.require_impl()
        store = GrantStore()
        store.reserve("zeta", "a")
        store.reserve("acme", "a")
        index = RepositoryIndex(store)
        index.register_project("zeta-thing", "other")
        index.register_project("acme-thing", "a")
        self.assertEqual(
            index.project_detail("zeta-thing")["namespaces"],
            [{"name": "zeta", "owned": False}],
        )
        self.assertEqual(
            index.project_detail("acme-thing")["namespaces"],
            [{"name": "acme", "owned": True}],
        )

    def test_project_detail_matched_owned(self):
        self.require_impl()
        _, index = self.make_index()
        index.register_project("acme-widgets-sprocket", "acme-corp")
        self.assertEqual(
            index.project_detail("acme-widgets-sprocket")["namespaces"],
            [
                {"name": "acme", "owned": True},
                {"name": "acme-widgets", "owned": True},
            ],
        )

    def test_project_detail_grandfathered_unowned(self):
        self.require_impl()
        _, index = self.make_index()
        index.register_project("acme-legacy", "mallory")
        index.grandfathered.add("acme-legacy")
        self.assertEqual(
            index.project_detail("acme-legacy")["namespaces"],
            [{"name": "acme", "owned": False}],
