            f'{self.namespace!r}; upload by {owner!r} denied')


class GrandfatheredRegistry:
    """Track normalized project names exempt from namespace upload checks."""

    def __init__(self, projects=()):
        self._projects = set()
        for project in projects:
            self.add(project)

    def __len__(self):
        return len(self._projects)

    def __contains__(self, project):
        return (isinstance(project, str)
                and normalize_name(project) in self._projects)

    def add(self, project):
        """Exempt one exact project name, without exempting its descendants."""
        self._projects.add(_validate_namespace(project))

    def discard(self, project):
        """Remove an exemption if it exists."""
        self._projects.discard(normalize_name(project))

    def covers(self, project):
        """Return whether the normalized project has an exemption."""
        return project in self

    def projects(self):
        """Return exempt project names in sorted order."""
        return sorted(self._projects)


def authorize_upload(project, owner, store, grandfathered=None, *,
                     raise_on_conflict=False):
    """Return whether an upload is allowed, optionally raising on conflict."""
    _validate_owner(owner)
